forensics_parse.source:
const item = $input.first();

const raw =
  item.json?.choices?.[0]?.message?.content;

if (!raw) {
  throw new Error(
    'Gemini Forensics returned no content.'
  );
}


// ==================================================
// PARSE GEMINI JSON
// ==================================================

let cleaned =
  String(raw)
    .trim()
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '');

let analysis;

try {

  analysis =
    JSON.parse(cleaned);

} catch (err) {

  throw new Error(
    'Gemini forensic JSON parse failed: ' +
    err.message +
    '\nRAW:\n' +
    cleaned
  );
}


// ==================================================
// SOURCES
// ==================================================

const referenceMedia =
  $('Prepare Reference Media').first().json;

const context =
  $('Build Recreation Context').first().json;


// ==================================================
// HELPERS
// ==================================================

function arr(value) {

  return Array.isArray(value)
    ? value
    : [];
}


function clean(value) {

  if (
    value === null ||
    value === undefined
  ) {
    return '';
  }

  return String(value).trim();
}


function timeToSeconds(value) {

  if (
    value === null ||
    value === undefined ||
    value === ''
  ) {
    return 0;
  }

  const parts =
    String(value)
      .trim()
      .split(':');

  if (parts.length === 3) {

    return (
      (Number(parts[0]) || 0) * 3600 +
      (Number(parts[1]) || 0) * 60 +
      (Number(parts[2]) || 0)
    );
  }

  if (parts.length === 2) {

    return (
      (Number(parts[0]) || 0) * 60 +
      (Number(parts[1]) || 0)
    );
  }

  return Number(parts[0]) || 0;
}


function itemToText(value) {

  if (
    value === null ||
    value === undefined
  ) {
    return '';
  }

  if (typeof value === 'string') {
    return clean(value);
  }

  if (typeof value === 'number') {
    return String(value);
  }

  if (typeof value === 'object') {

    const parts = [];

    if (value.type) {
      parts.push(clean(value.type));
    }

    if (value.description) {
      parts.push(clean(value.description));
    }

    if (value.action) {
      parts.push(clean(value.action));
    }

    if (value.name) {
      parts.push(clean(value.name));
    }

    if (value.notes) {
      parts.push(clean(value.notes));
    }

    if (parts.length) {
      return parts.join(': ');
    }

    try {
      return JSON.stringify(value);
    } catch {
      return '';
    }
  }

  return clean(value);
}


function normalizeArray(value) {

  return arr(value)
    .map(itemToText)
    .filter(Boolean);
}


function hasWardrobeContent(state) {

  if (!state) {
    return false;
  }

  const scalarFields = [
    'top',
    'bottom',
    'dress',
    'outerwear',
    'shoes',
    'socks',
    'headwear',
    'eyewear',
    'fit_notes',
    'styling_notes'
  ];

  const scalarPresent =
    scalarFields.some(
      key =>
        clean(state[key]).length > 0
    );


  const listPresent =
    [
      state.accessories,
      state.jewelry,
      state.colors,
      state.materials
    ].some(
      value =>
        Array.isArray(value) &&
        value.length > 0
    );


  return (
    scalarPresent ||
    listPresent
  );
}


function normalizeWardrobeState(state) {

  return {

    state_id:
      clean(state?.state_id) ||
      'state_1',

    time_range:
      clean(state?.time_range),

    top:
      clean(state?.top),

    bottom:
      clean(state?.bottom),

    dress:
      clean(state?.dress),

    outerwear:
      clean(state?.outerwear),

    shoes:
      clean(state?.shoes),

    socks:
      clean(state?.socks),

    accessories:
      normalizeArray(
        state?.accessories
      ),

    jewelry:
      normalizeArray(
        state?.jewelry
      ),

    headwear:
      clean(state?.headwear),

    eyewear:
      clean(state?.eyewear),

    colors:
      normalizeArray(
        state?.colors
      ),

    materials:
      normalizeArray(
        state?.materials
      ),

    fit_notes:
      clean(state?.fit_notes),

    styling_notes:
      clean(state?.styling_notes),

    change_from_previous_state:
      clean(
        state?.change_from_previous_state
      )
  };
}


function fallbackWardrobeState(
  stateId,
  duration,
  description
) {

  return {

    state_id:
      stateId,

    time_range:
      `00:00.000-${duration.toFixed(3)}`,

    top:
      clean(description),

    bottom: '',
    dress: '',
    outerwear: '',
    shoes: '',
    socks: '',

    accessories: [],
    jewelry: [],
    headwear: '',
    eyewear: '',
    colors: [],
    materials: [],
    fit_notes: '',

    styling_notes:
      clean(description),

    change_from_previous_state:
      ''
  };
}


// ==================================================
// VALIDATION
// ==================================================

const creativeDuration =
  Number(
    analysis.creative_duration_seconds || 0
  );


if (!creativeDuration) {

  throw new Error(
    'Gemini did not return creative_duration_seconds.'
  );
}


const global =
  analysis.global_scene_lock || {};


if (
  !Array.isArray(analysis.shots) ||
  !analysis.shots.length
) {

  throw new Error(
    'Gemini output contains no shots.'
  );
}


// ==================================================
// HARD IDENTITY RULES
// ==================================================

const identityRules = {

  permanent_features_locked:
    true,

  source_performer_appearance_must_not_override_identity:
    true,

  allowed_changes: [
    'choreography',
    'pose',
    'facial_expression',
    'gaze',
    'wardrobe',
    'shoes',
    'accessories',
    'jewelry',
    'props',
    'location',
    'background',
    'lighting',
    'camera_behavior'
  ],

  forbidden_changes: [
    'face_identity',
    'facial_proportions',
    'eye_color',
    'eye_shape',
    'nose_shape',
    'mouth_structure',
    'skin_tone',
    'natural_hair_color',
    'hair_length',
    'hair_texture',
    'hairstyle_identity',
    'body_proportions',
    'physique',
    'height_impression',
    'overall_likeness'
  ]
};


// ==================================================
// WARDROBE DESCRIPTIONS
// Supports TOP LEVEL + old nested format
// ==================================================

const ariaWardrobeDescription =
  clean(
    analysis.aria_wardrobe_description ||
    global.aria_wardrobe_description ||
    analysis.aria_outfit ||
    global.aria_outfit ||
    ''
  );


const nicoleWardrobeDescription =
  clean(
    analysis.nicole_wardrobe_description ||
    global.nicole_wardrobe_description ||
    analysis.nicole_outfit ||
    global.nicole_outfit ||
    ''
  );


// ==================================================
// WARDROBE STATES
// ==================================================

let ariaWardrobeStates =
  arr(
    analysis.aria_wardrobe_states ||
    global.aria_wardrobe_states
  )
    .map(normalizeWardrobeState)
    .filter(hasWardrobeContent);


let nicoleWardrobeStates =
  arr(
    analysis.nicole_wardrobe_states ||
    global.nicole_wardrobe_states
  )
    .map(normalizeWardrobeState)
    .filter(hasWardrobeContent);


// ==================================================
// VISIBILITY
// ==================================================

const ariaVisible =
  analysis.shots.some(
    shot =>
      shot?.aria_motion?.visible === true
  );


const nicoleVisible =
  analysis.shots.some(
    shot =>
      shot?.nicole_motion?.visible === true
  );


// ==================================================
// WARDROBE FALLBACK
// ==================================================

if (
  ariaVisible &&
  !ariaWardrobeStates.length &&
  ariaWardrobeDescription
) {

  ariaWardrobeStates = [
    fallbackWardrobeState(
      'state_1',
      creativeDuration,
      ariaWardrobeDescription
    )
  ];
}


if (
  nicoleVisible &&
  !nicoleWardrobeStates.length &&
  nicoleWardrobeDescription
) {

  nicoleWardrobeStates = [
    fallbackWardrobeState(
      'state_1',
      creativeDuration,
      nicoleWardrobeDescription
    )
  ];
}


// ==================================================
// STOP BEFORE WAN IF WARDROBE IS ACTUALLY MISSING
// ==================================================

if (
  ariaVisible &&
  !ariaWardrobeStates.length
) {

  throw new Error(
    'Aria is visible but Gemini returned no usable source-video wardrobe. Re-run Gemini Forensics before WAN.'
  );
}


if (
  nicoleVisible &&
  !nicoleWardrobeStates.length
) {

  throw new Error(
    'Nicole is visible but Gemini returned no usable source-video wardrobe. Re-run Gemini Forensics before WAN.'
  );
}


// ==================================================
// NORMALIZE SHOTS
// ==================================================

const shots =
  [...analysis.shots]
    .sort(
      (a, b) =>
        timeToSeconds(a.start) -
        timeToSeconds(b.start)
    );


const ariaStateIds =
  ariaWardrobeStates.map(
    state =>
      state.state_id
  );


const nicoleStateIds =
  nicoleWardrobeStates.map(
    state =>
      state.state_id
  );


for (const shot of shots) {

  const start =
    timeToSeconds(
      shot.start
    );

  const end =
    timeToSeconds(
      shot.end
    );


  if (end <= start) {

    throw new Error(
      `Invalid shot timing: ${shot.start} → ${shot.end}`
    );
  }


  if (
    end >
    creativeDuration + 0.5
  ) {

    throw new Error(
      `Shot ${shot.shot_id} exceeds creative duration.`
    );
  }


  // ----------------------------------------------
  // Normalize movement arrays
  // ----------------------------------------------

  if (shot.aria_motion) {

    shot.aria_motion.movement_sequence =
      arr(
        shot.aria_motion.movement_sequence
      )
        .map(action => {

          if (
            typeof action === 'string'
          ) {

            return {
              time: '',
              action:
                clean(action)
            };
          }

          return {
            time:
              clean(action?.time),

            action:
              clean(
                action?.action ||
                action?.description
              )
          };
        })
        .filter(
          x =>
            x.action
        );


    shot.aria_motion.props =
      normalizeArray(
        shot.aria_motion.props
      );
  }


  if (shot.nicole_motion) {

    shot.nicole_motion.movement_sequence =
      arr(
        shot.nicole_motion.movement_sequence
      )
        .map(action => {

          if (
            typeof action === 'string'
          ) {

            return {
              time: '',
              action:
                clean(action)
            };
          }

          return {
            time:
              clean(action?.time),

            action:
              clean(
                action?.action ||
                action?.description
              )
          };
        })
        .filter(
          x =>
            x.action
        );


    shot.nicole_motion.props =
      normalizeArray(
        shot.nicole_motion.props
      );
  }


  // ----------------------------------------------
  // Aria wardrobe state
  // ----------------------------------------------

  if (
    shot?.aria_motion?.visible === true
  ) {

    let stateId =
      clean(
        shot.aria_motion.wardrobe_state
      );


    if (
      !stateId &&
      ariaStateIds.length === 1
    ) {

      stateId =
        ariaStateIds[0];
    }


    if (
      stateId &&
      !ariaStateIds.includes(stateId)
    ) {

      if (
        ariaStateIds.length === 1
      ) {

        stateId =
          ariaStateIds[0];

      } else {

        throw new Error(
          `Unknown Aria wardrobe state "${stateId}" in shot ${shot.shot_id}.`
        );
      }
    }


    if (
      !stateId &&
      ariaStateIds.length > 1
    ) {

      throw new Error(
        `Shot ${shot.shot_id} does not specify Aria wardrobe state.`
      );
    }


    shot.aria_motion.wardrobe_state =
      stateId;
  }


  // ----------------------------------------------
  // Nicole wardrobe state
  // ----------------------------------------------

  if (
    shot?.nicole_motion?.visible === true
  ) {

    let stateId =
      clean(
        shot.nicole_motion.wardrobe_state
      );


    if (
      !stateId &&
      nicoleStateIds.length === 1
    ) {

      stateId =
        nicoleStateIds[0];
    }


    if (
      stateId &&
      !nicoleStateIds.includes(stateId)
    ) {

      if (
        nicoleStateIds.length === 1
      ) {

        stateId =
          nicoleStateIds[0];

      } else {

        throw new Error(
          `Unknown Nicole wardrobe state "${stateId}" in shot ${shot.shot_id}.`
        );
      }
    }


    if (
      !stateId &&
      nicoleStateIds.length > 1
    ) {

      throw new Error(
        `Shot ${shot.shot_id} does not specify Nicole wardrobe state.`
      );
    }


    shot.nicole_motion.wardrobe_state =
      stateId;
  }


  // ----------------------------------------------
  // Normalize transition
  // ----------------------------------------------

  if (
    shot.transition_to_next &&
    typeof shot.transition_to_next === 'object'
  ) {

    const type =
      clean(
        shot.transition_to_next.type
      );

    const description =
      clean(
        shot.transition_to_next.description
      );


    shot.transition_to_next_text =
      [type, description]
        .filter(Boolean)
        .join(': ');

  } else {

    shot.transition_to_next_text =
      clean(
        shot.transition_to_next
      );
  }
}


// ==================================================
// NORMALIZED ANALYSIS
// ==================================================

const normalizedAnalysis = {

  ...analysis,

  creative_duration_seconds:
    creativeDuration,

  global_scene_lock:
    global,

  identity_preservation_rules:
    identityRules,

  aria_wardrobe_description:
    ariaWardrobeDescription,

  nicole_wardrobe_description:
    nicoleWardrobeDescription,

  aria_wardrobe_states:
    ariaWardrobeStates,

  nicole_wardrobe_states:
    nicoleWardrobeStates,

  shots
};


// ==================================================
// OUTPUT
// ==================================================

return [
  {
    json: {

      job_id:
        context.job_id,

      character:
        context.character,

      character_name:
        context.character_name ||
        context.character_profile?.name ||
        context.character,

      character_mode:
        context.character_mode ||
        context.character_profile?.character_mode ||
        'SINGLE',

      platform:
        context.platform,

      user_instructions:
        context.user_instructions || '',


      reference_video_url:
        referenceMedia.reference_video_url,

      original_reference_video_url:
        referenceMedia.original_reference_video_url ||
        referenceMedia.reference_video_url,


      creative_duration_seconds:
        creativeDuration,


      identity_images:
        referenceMedia.identity_images ||
        context.character_profile?.identity_images ||
        [],

      identity_groups:
        referenceMedia.identity_groups ||
        context.identity_groups ||
        context.character_profile?.identity_groups ||
        { aria: [], nicole: [] },

      identity_lock:
        referenceMedia.identity_lock ||
        context.character_profile?.identity_lock ||
        context.identity_lock ||
        {},


      identity_preservation_rules:
        identityRules,


      aria_wardrobe_description:
        ariaWardrobeDescription,

      nicole_wardrobe_description:
        nicoleWardrobeDescription,


      aria_wardrobe_states:
        ariaWardrobeStates,

      nicole_wardrobe_states:
        nicoleWardrobeStates,


      motion_analysis:
        normalizedAnalysis,

      global_scene_lock:
        global,

      shots,


      critical_motion_features:
        arr(
          analysis.critical_motion_features
        ),

      critical_camera_features:
        arr(
          analysis.critical_camera_features
        ),

      critical_timing_features:
        arr(
          analysis.critical_timing_features
        ),

      critical_transition_features:
        arr(
          analysis.critical_transition_features
        ),

      critical_wardrobe_features:
        arr(
          analysis.critical_wardrobe_features
        ),

      uncertainties:
        arr(
          analysis.uncertainties
        ),


      status:
        'GEMINI_FORENSICS_PARSED'
    }
  }
];

grok_parse.source:
const item = $input.first();
const raw = item.json?.choices?.[0]?.message?.content;
if (!raw) throw new Error('Grok returned no segment plan.');
let cleaned = String(raw).trim().replace(/^\x60\x60\x60json\s*/i,'').replace(/^\x60\x60\x60\s*/i,'').replace(/\s*\x60\x60\x60$/i,'');
let plan;
try { plan = JSON.parse(cleaned); } catch (err) { throw new Error('Grok segment-plan JSON parse failed: '+err.message+'\nRAW:\n'+cleaned); }
const blueprint = $('Parse Gemini Forensics').first().json;
const context = $('Build Recreation Context').first().json;
const creativeDuration = Number(blueprint.creative_duration_seconds || 0);
if (!creativeDuration) throw new Error('creative_duration_seconds is missing.');
const clean = v => v == null ? '' : String(v).replace(/\s+/g,' ').trim();
const num = (v,f=0) => Number.isFinite(Number(v)) ? Number(v) : f;
const clampInt = (v,min,max) => Math.max(min,Math.min(max,Math.round(num(v))));
const rawSegments = Array.isArray(plan.segments) ? plan.segments : [];
if (!rawSegments.length) throw new Error('Grok returned no segments.');
const segments = rawSegments.map((s,index)=>{
  const sourceStart=num(s.source_start), sourceEnd=num(s.source_end);
  if(sourceEnd<=sourceStart) throw new Error(`Invalid segment ${index}: source_end must be greater than source_start.`);
  const sourceDuration=sourceEnd-sourceStart;
  if(sourceDuration>10.25) throw new Error(`Segment ${index} is too long (${sourceDuration.toFixed(2)}s). Max source segment is 10s. Re-run Grok.`);
  const outputDuration=clampInt(s.output_duration || sourceDuration,2,10);
  const wanPrompt=clean(s.wan_prompt);
  if(!wanPrompt) throw new Error(`Segment ${index} has no wan_prompt.`);
  if(wanPrompt.length>1400) throw new Error(`Segment ${index} wan_prompt is too long: ${wanPrompt.length} chars.`);
  return {
    segment_index:index, mode:'REFERENCE', source_start:sourceStart, source_end:sourceEnd,
    source_duration:Number(sourceDuration.toFixed(3)), output_duration:outputDuration,
    source_start_timestamp:clean(s.source_start_timestamp), source_end_timestamp:clean(s.source_end_timestamp),
    wardrobe_state:s.wardrobe_state || {aria:'',nicole:''}, start_state:clean(s.start_state), end_state:clean(s.end_state),
    continuity_from_previous:clean(s.continuity_from_previous), camera:clean(s.camera),
    critical_actions:Array.isArray(s.critical_actions)?s.critical_actions.map(clean).filter(Boolean):[],
    transition:clean(s.transition), wan_prompt:wanPrompt
  };
}).sort((a,b)=>a.source_start-b.source_start);
segments.forEach((s,i)=>{s.segment_index=i;s.mode='REFERENCE';});
if(Math.abs(segments[0].source_start)>0.25) throw new Error(`First segment must start at 0. Got ${segments[0].source_start}.`);
for(let i=1;i<segments.length;i++){
  const gap=segments[i].source_start-segments[i-1].source_end;
  if(Math.abs(gap)>0.35) throw new Error(`Segment timeline gap/overlap between ${i-1} and ${i}: ${gap.toFixed(3)}s.`);
}
const finalEnd=segments[segments.length-1].source_end;
if(Math.abs(finalEnd-creativeDuration)>0.75) throw new Error(`Segment plan does not cover full creative duration. Final end=${finalEnd}, creative=${creativeDuration}.`);
const identityImages=blueprint.identity_images || context.identity_images || context.character_profile?.identity_images || [];
const identityGroups=blueprint.identity_groups || context.identity_groups || context.character_profile?.identity_groups || {aria:[],nicole:[]};
if(!identityImages.length) throw new Error('Identity images are missing.');
if(context.character_mode==='DUO' && (!identityGroups.aria?.length || !identityGroups.nicole?.length)) throw new Error('DUO mode requires Aria and Nicole identity groups.');
return [{json:{
  job_id:context.job_id, character:context.character, character_name:context.character_name||context.character_profile?.name||context.character,
  character_mode:context.character_mode, platform:context.platform, user_instructions:context.user_instructions||'',
  reference_video_url:blueprint.reference_video_url,
  original_reference_video_url:blueprint.original_reference_video_url||blueprint.reference_video_url,
  creative_duration_seconds:creativeDuration,
  identity_images:identityImages, identity_groups:identityGroups,
  identity_lock:blueprint.identity_lock||context.identity_lock||{}, total_duration:num(plan.total_duration,creativeDuration),
  segment_count:segments.length, segments, current_segment:segments[0], current_segment_index:0,
  status:'GROK_REFERENCE_SEGMENT_PLAN_READY'
}}];

wan_initial_prepare.source:
const item = $input.first();

const trimmedVideoUrl = item.json?.video?.url;
if (!trimmedVideoUrl) {
  throw new Error('fal trim completed but returned no video URL.');
}

const plan = $('Parse Grok Segment Plan').first().json;
const context = $('Build Recreation Context').first().json;
const segment = plan.current_segment;

if (!segment) {
  throw new Error('Initial segment is missing.');
}

const identityImages = (plan.identity_images || [])
  .filter(url => url && url.startsWith('http'));

const identityGroups =
  plan.identity_groups || { aria: [], nicole: [] };

if (!identityImages.length) {
  throw new Error('Identity images are missing.');
}

let identityRule = '';

if (context.character_mode === 'DUO') {
  const a = identityGroups.aria?.length || 0;
  const n = identityGroups.nicole?.length || 0;

  identityRule =
    `IDENTITY ABSOLUTE. Images1-${a}=Aria; Images${a + 1}-${a + n}=Nicole. ` +
    `Each image group depicts the SAME exact person. Preserve exact recognizable faces, facial geometry, eyes, natural skin tone, natural hair color/length/texture, body proportions, physique and overall likeness. ` +
    `Never copy source performer physical identity. Never swap or blend Aria and Nicole.`;
} else {
  identityRule =
    `IDENTITY ABSOLUTE. Images1-${identityImages.length} all depict ${context.character_name}; together they are the ONLY authority for physical identity. ` +
    `Preserve exact recognizable face, facial geometry, eyes, natural skin tone, natural hair color/length/texture, body proportions, physique and overall likeness. ` +
    `Never copy the source performer's face, body, skin or hair identity.`;
}

const roles =
  'Video1=ORIGINAL SOURCE SEGMENT. Video1 controls choreography, pose, expression, gaze, action order, timing, wardrobe, props, scene, transition and camera ONLY. Video1 must NEVER redefine physical identity.';

const priority =
  'PRIORITY: identity images > physical identity; Video1 > motion/wardrobe/camera/timing.';

const base = String(segment.wan_prompt || '')
  .replace(/\s+/g, ' ')
  .trim();

if (!base) {
  throw new Error('Initial segment WAN prompt is missing.');
}

const suffix =
  'Recreate this source segment as closely as possible. No UI, logos, watermarks, usernames, subtitles or random text.';

const max = 1900;
const fixed = `${identityRule}\n${roles}\n${priority}\n`;
const remaining = max - fixed.length - suffix.length - 3;

const safe =
  base.length <= remaining
    ? base
    : base.slice(0, Math.max(1, remaining - 1)).trim() + '…';

const prompt = `${fixed}${safe}\n${suffix}`;

return [{
  json: {
    ...plan,
    initial_reference_video_url: trimmedVideoUrl,
    wan_recreation_prompt: prompt,
    wan_prompt_characters: prompt.length,
    wan_output_duration_seconds: Number(segment.output_duration),
    current_segment_index: 0,
    current_segment: segment,
    status: 'INITIAL_IDENTITY_LOCKED_REFERENCE_SEGMENT_READY'
  }
}];

wan_next_prepare.source:
const item = $input.first();

const previousTailUrl = item.json?.video?.url;
if (!previousTailUrl) {
  throw new Error('Previous-tail trim returned no video URL.');
}

const states = $('Prepare Previous Tail Trim').all();
const state = states[states.length - 1].json;

const context =
  $('Build Recreation Context').first().json;

const segment =
  state.segments?.[state.next_segment_index];

if (!segment) {
  throw new Error('Next segment is missing.');
}

const images = (state.identity_images || [])
  .filter(url => url && url.startsWith('http'));

const groups =
  state.identity_groups || { aria: [], nicole: [] };

if (!images.length) {
  throw new Error('Identity images missing for next segment.');
}

let identityRule = '';

if (state.character_mode === 'DUO') {
  const a = groups.aria?.length || 0;
  const n = groups.nicole?.length || 0;

  identityRule =
    `IDENTITY ABSOLUTE. Images1-${a}=Aria; Images${a + 1}-${a + n}=Nicole. ` +
    `Images are the ONLY authority for physical identity. Preserve exact recognizable faces, facial geometry, eyes, natural skin tone, natural hair color/length/texture, body proportions, physique and likeness. Never swap or blend identities.`;
} else {
  identityRule =
    `IDENTITY ABSOLUTE. Images1-${images.length} all depict ${state.character_name}; together they are the ONLY physical identity authority. ` +
    `Preserve exact recognizable face, facial geometry, eyes, natural skin tone, natural hair color/length/texture, body proportions, physique and likeness.`;
}

const roles =
  'Video1=ORIGINAL SOURCE SEGMENT: authoritative for choreography, pose, expression, action order, timing, wardrobe, props, scene, transition and camera ONLY. ' +
  'Video2=PREVIOUS GENERATED TAIL: continuity ONLY for pose, screen position, movement direction, camera, scene and wardrobe. Video1 and Video2 must NEVER redefine physical identity.';

const priority =
  'PRIORITY: identity images > physical identity; Video1 > motion/wardrobe/camera/timing; Video2 > continuity only.';

const continuity = String(
  segment.continuity_from_previous ||
  segment.start_state ||
  ''
)
  .replace(/\s+/g, ' ')
  .trim();

const base = String(segment.wan_prompt || '')
  .replace(/\s+/g, ' ')
  .trim();

if (!base) {
  throw new Error('Next segment WAN prompt is missing.');
}

const suffix =
  'Generate only this next source segment. Preserve identity from the images in every frame. No UI, logos, watermarks, subtitles or random text.';

const max = 1900;

const fixed =
  `${identityRule}\n` +
  `${roles}\n` +
  `${priority}\n` +
  (continuity ? `Continuity: ${continuity}\n` : '');

const remaining =
  max -
  fixed.length -
  suffix.length -
  3;

const safe =
  base.length <= remaining
    ? base
    : base.slice(0, Math.max(1, remaining - 1)).trim() + '…';

const prompt =
  `${fixed}${safe}\n${suffix}`;

return [{
  json: {
    ...state,
    current_segment: segment,
    source_segment_video_url:
      state.source_segment_video_url,
    previous_generated_tail_url:
      previousTailUrl,
    wan_recreation_prompt:
      prompt,
    wan_prompt_characters:
      prompt.length,
    wan_output_duration_seconds:
      Number(segment.output_duration),
    status:
      'IDENTITY_LOCKED_REFERENCE_SEGMENT_READY'
  }
}];

