const item=$input.first();
const raw=item.json?.choices?.[0]?.message?.content;
if(!raw) throw new Error('Gemini QA returned no content.');
let cleaned=String(raw).trim().replace(/^\x60\x60\x60json\s*/i,'').replace(/^\x60\x60\x60\s*/i,'').replace(/\s*\x60\x60\x60$/i,'');
let qa; try{qa=JSON.parse(cleaned);}catch(err){throw new Error('Gemini QA JSON parse failed: '+err.message+'\nRAW:\n'+cleaned);}
const source=$('Prepare Generated Video1').first().json;
const context=$('Build Recreation Context').first().json;
const num=(v,f=0)=>Number.isFinite(Number(v))?Number(v):f;
const bool=(v,f=false)=>typeof v==='boolean'?v:(v==='true'?true:(v==='false'?false:f));
const arr=v=>Array.isArray(v)?v:[];
const normalized={
 identity_match:num(qa.identity_match),face_identity_match:num(qa.face_identity_match),identity_consistency_across_video:num(qa.identity_consistency_across_video),
 aria_identity_match:num(qa.aria_identity_match),nicole_identity_match:num(qa.nicole_identity_match),identity_swap_detected:bool(qa.identity_swap_detected),identity_blending_detected:bool(qa.identity_blending_detected),
 source_choreography_match:num(qa.source_choreography_match,num(qa.choreography_match)),choreography_match:num(qa.choreography_match),action_order_match:num(qa.action_order_match),timing_match:num(qa.timing_match),transition_match:num(qa.transition_match),wardrobe_plan_match:num(qa.wardrobe_plan_match),camera_match:num(qa.camera_match),environment_match:num(qa.environment_match),visual_quality:num(qa.visual_quality),clean_output:bool(qa.clean_output),
 critical_failures:arr(qa.critical_failures),major_issues:arr(qa.major_issues),minor_issues:arr(qa.minor_issues),regeneration_instructions:arr(qa.regeneration_instructions),overall_score:num(qa.overall_score),gemini_approved:bool(qa.approved)
};
const issueText=[...normalized.critical_failures,...normalized.major_issues].join(' ').toLowerCase();
const hasCriticalFailure=normalized.critical_failures.length>0 || issueText.includes('severely truncated') || issueText.includes('missing segment') || issueText.includes('majority of the choreography is missing') || issueText.includes('wrong performer') || issueText.includes('identity swap') || issueText.includes('identity blending') || issueText.includes('major identity drift') || issueText.includes('completely omitted') || issueText.includes('wrong sequence') || issueText.includes('video ends early');
const hasCriticalWardrobeFailure=issueText.includes('wardrobe change is missing') || issueText.includes('outfit change is missing') || issueText.includes('wardrobe transition is missing') || issueText.includes('required wardrobe state is missing') || issueText.includes('never changes outfit') || issueText.includes('wrong wardrobe throughout') || issueText.includes('wardrobe sequence is incorrect');
const identityGood=normalized.identity_match>=0.88 && normalized.face_identity_match>=0.88 && normalized.identity_consistency_across_video>=0.90;
const motionGood=normalized.source_choreography_match>=0.80 && normalized.choreography_match>=0.80 && normalized.action_order_match>=0.82 && normalized.timing_match>=0.75;
const structureGood=normalized.transition_match>=0.80 && normalized.camera_match>=0.75 && normalized.environment_match>=0.75;
const qualityGood=normalized.visual_quality>=0.80 && normalized.clean_output===true;
const identitySafe=!normalized.identity_swap_detected && !normalized.identity_blending_detected;
const approved=identityGood&&motionGood&&structureGood&&qualityGood&&identitySafe&&!hasCriticalFailure&&!hasCriticalWardrobeFailure;
const minorIssues=[...normalized.minor_issues];
if(normalized.wardrobe_plan_match<0.80&&!hasCriticalWardrobeFailure) minorIssues.push('Minor wardrobe-detail mismatch accepted because identity, choreography, timing and narrative structure passed.');
const qaDecision=approved?(minorIssues.length?'APPROVED_WITH_MINOR_ISSUES':'APPROVED'):'REJECTED';
return [{json:{
 job_id:context.job_id,character:context.character,character_name:context.character_name||context.character_profile?.name||context.character,character_mode:context.character_mode,platform:context.platform,
 generated_video_url:source.generated_video_url,original_reference_video_url:source.original_reference_video_url,creative_duration_seconds:source.creative_duration_seconds,segment_count:source.segment_count,generation_type:source.generation_type,...normalized,
 minor_issues:minorIssues,approved,qa_decision:qaDecision,qa_status:approved?(minorIssues.length?'QA_APPROVED_WITH_MINOR_ISSUES':'QA_APPROVED'):'QA_REJECTED'
}}];

