context_build.source:
const item = $input.first();

const characterRaw = item.json.character || item.json.Character || '';
const character = String(characterRaw)
  .trim()
  .toUpperCase()
  .replace(/\s*\+\s*/g, '_')
  .replace(/\s+/g, '_');

// ==================================================
// IDENTITY REFERENCE LIBRARY
// ==================================================
// Keep the existing primary reference as slot 1.
// After generating the extra identity anchors, paste their public URLs
// into slots 2 and 3 below. Empty slots are ignored automatically.
// Recommended per character:
// 1 = primary / frontal identity reference
// 2 = 3/4 face identity anchor
// 3 = neutral full-body identity anchor

// Original identity slots are supplied by environment-backed URLs at runtime.
const ARIA_IDENTITY_IMAGES = Array.isArray(item.json.aria_identity_urls) ? item.json.aria_identity_urls : [];
const NICOLE_IDENTITY_IMAGES = Array.isArray(item.json.nicole_identity_urls) ? item.json.nicole_identity_urls : [];

const profiles = {
  ARIA: {
    name: 'Aria Vale',
    platform: 'TIKTOK',
    character_mode: 'SINGLE',
    identity_images: ARIA_IDENTITY_IMAGES,
    identity_groups: { aria: ARIA_IDENTITY_IMAGES, nicole: [] },
    identity_lock: {
      hair_color: 'brown',
      hair_length: 'long',
      hair_texture: 'natural straight to softly wavy',
      eye_color: 'hazel',
      skin_tone: 'olive',
      face_identity: 'must match Aria reference set exactly',
      body_type: 'toned feminine physique',
      height_impression: '1.72 m',
      permanent_identity_locked: true
    }
  },
  NICOLE: {
    name: 'Nicole',
    platform: 'INSTAGRAM',
    character_mode: 'SINGLE',
    identity_images: NICOLE_IDENTITY_IMAGES,
    identity_groups: { aria: [], nicole: NICOLE_IDENTITY_IMAGES },
    identity_lock: {
      hair_color: 'brown',
      hair_length: 'long',
      hair_texture: 'use Nicole reference set exactly',
      eye_color: 'use Nicole reference set exactly',
      skin_tone: 'use Nicole reference set exactly',
      face_identity: 'must match Nicole reference set exactly',
      body_type: 'use Nicole reference proportions exactly',
      height_impression: '1.72 m',
      permanent_identity_locked: true
    }
  },
  ARIA_NICOLE: {
    name: 'Aria Vale and Nicole',
    platform: 'BOTH',
    character_mode: 'DUO',
    identity_images: [...ARIA_IDENTITY_IMAGES, ...NICOLE_IDENTITY_IMAGES],
    identity_groups: { aria: ARIA_IDENTITY_IMAGES, nicole: NICOLE_IDENTITY_IMAGES },
    identity_lock: {
      aria: {
        hair_color: 'brown', hair_length: 'long', eye_color: 'hazel', skin_tone: 'olive',
        face_identity: 'Aria reference set only'
      },
      nicole: {
        hair_color: 'brown', hair_length: 'long', eye_color: 'Nicole reference set only',
        skin_tone: 'Nicole reference set only', face_identity: 'Nicole reference set only'
      },
      never_swap_identities: true,
      never_blend_identities: true,
      permanent_identity_locked: true
    }
  }
};

const profile = profiles[character];
if (!profile) {
  throw new Error(`Unsupported character "${characterRaw}". Expected ARIA, NICOLE or ARIA_NICOLE.`);
}
if (!profile.identity_images.length) throw new Error('Identity reference images are missing.');

const jobId = `${Math.floor(Math.random() * 90000) + 10000}_${Date.now()}`;
const userInstructions = item.json.instructions || item.json.user_instructions || '';

return [{
  json: {
    ...item.json,
    job_id: jobId,
    character,
    character_name: profile.name,
    character_mode: profile.character_mode,
    platform: profile.platform,
    character_profile: profile,
    identity_images: profile.identity_images,
    identity_groups: profile.identity_groups,
    identity_lock: profile.identity_lock,
    user_instructions: userInstructions,
    status: 'RECREATION_CONTEXT_BUILT'
  },
  binary: item.binary || {}
}];
